import React, { useState, useEffect, useRef } from 'react';
import io from 'socket.io-client';
import './App.css';

function App() {
  const [socket, setSocket] = useState(null);
  const [isHosting, setIsHosting] = useState(false);
  const [isJoined, setIsJoined] = useState(false);
  const userVideo = useRef();

  useEffect(() => {
    const newSocket = io.connect('http://localhost:3001');
    setSocket(newSocket);

    newSocket.on('host', () => {
      setIsHosting(true);
    });

    newSocket.on('join', () => {
      setIsJoined(true);
    });

    // Request access to the user's camera and microphone
    navigator.mediaDevices.getUserMedia({ video: true, audio: true })
      .then(stream => {
        // Set the source of the video element to the user's stream
        userVideo.current.srcObject = stream;
      })
      .catch(err => {
        console.error('Error accessing media devices.', err);
      });

    return () => newSocket.close();
  }, []);

  const handleHostMeeting = () => {
    if (socket && !isHosting) {
      socket.emit('host');
    }
  };

  const handleJoinMeeting = () => {
    if (socket && !isJoined) {
      socket.emit('join');
    }
  };

  return (
    <div className="App">
      <main>
        <video ref={userVideo} id="userVideo" autoPlay muted></video>
        <div>
          <button id="hostButton" onClick={handleHostMeeting}>Host Meeting</button>
          <button id="joinButton" onClick={handleJoinMeeting}>Join Meeting</button>
        </div>
      </main>
    </div>
  );
}

export default App;
